import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, Bell, Check, ChevronDown, Clock3, ExternalLink, FolderKanban, Globe2, GripVertical, KeyRound, LayoutDashboard, LoaderCircle, LocateFixed, LogOut, Mail, Map as MapIcon, Maximize2, Minimize2, Moon, MoreHorizontal, Plus, RefreshCw, Save, Search, Send, Server, Settings2, ShieldCheck, Signal, SlidersHorizontal, Sun, Trash2, UserRound, X, Zap, ZoomIn, ZoomOut } from 'lucide-react';

const fmtTime = value => value ? new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : 'Not checked yet';
const hostOf = value => { try { return new URL(value).hostname; } catch { return value; } };
const initials = name => name.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
const apiFetch = (url, options = {}) => fetch(url, { ...options, credentials: 'include' });
const defaultMapPositions = [{ x: 19, y: 32 }, { x: 48, y: 23 }, { x: 79, y: 34 }, { x: 37, y: 72 }, { x: 72, y: 76 }];
const mapPosition = (app, index) => ({ x: Number(app.x ?? defaultMapPositions[index % defaultMapPositions.length].x), y: Number(app.y ?? defaultMapPositions[index % defaultMapPositions.length].y) });

function App() {
  const [apps, setApps] = useState([]); const [page, setPage] = useState('Overview'); const [search, setSearch] = useState('');
  const [user, setUser] = useState(null); const [authLoading, setAuthLoading] = useState(true); const [authMode, setAuthMode] = useState('login'); const [authError, setAuthError] = useState(''); const [authNotice, setAuthNotice] = useState(''); const [resetToken, setResetToken] = useState(''); const [settingsData, setSettingsData] = useState(null);
  const [modal, setModal] = useState(null); const [busy, setBusy] = useState(false); const [toast, setToast] = useState(''); const [lastUpdated, setLastUpdated] = useState(null); const [selected, setSelected] = useState(null);
  const [mapZoom, setMapZoom] = useState(1); const [mapFullscreen, setMapFullscreen] = useState(false); const [notificationsOpen, setNotificationsOpen] = useState(false); const [accountMenuOpen, setAccountMenuOpen] = useState(false);
  const [theme, setTheme] = useState(() => { try { return localStorage.getItem('appwatch.theme') === 'light' ? 'light' : 'dark'; } catch { return 'dark'; } });
  const dragRef = useRef(null); const suppressMapClick = useRef(false); const notificationsRef = useRef(null); const accountMenuRef = useRef(null);
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const verificationToken = params.get('verify'); const passwordToken = params.get('reset');
    if (verificationToken) {
      apiFetch('/api/auth/verify-email', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ token: verificationToken }) })
        .then(async r => { const result = await r.json(); if (!r.ok) throw new Error(result.error); setAuthNotice(result.message); })
        .catch(error => setAuthError(error.message || 'This verification link is invalid or has expired.'))
        .finally(() => { window.history.replaceState({}, '', window.location.pathname); setAuthLoading(false); });
      return;
    }
    if (passwordToken) { setResetToken(passwordToken); setAuthMode('reset'); window.history.replaceState({}, '', window.location.pathname); setAuthLoading(false); return; }
    apiFetch('/api/auth/me').then(async r => { if (r.ok) setUser((await r.json()).user); }).catch(() => {}).finally(() => setAuthLoading(false));
  }, []);
  const loadApps = useCallback(async () => { if (!user) return; try { const r = await apiFetch('/api/apps'); if (r.status === 401) { setUser(null); return; } if (!r.ok) throw new Error('API unavailable'); const data = await r.json(); if (!dragRef.current) setApps(data); setLastUpdated(new Date()); } catch { setToast('Could not connect to AppWatch API. Check the backend connection.'); } }, [user]);
  const loadSettings = useCallback(async () => { if (!user) return; try { const r = await apiFetch('/api/settings'); if (r.status === 401) { setUser(null); return; } if (!r.ok) throw new Error(); setSettingsData(await r.json()); } catch { setToast('Could not load account settings'); } }, [user]);
  useEffect(() => { if (!user) { setApps([]); setSettingsData(null); return; } loadApps(); loadSettings(); const id = setInterval(loadApps, 8000); return () => clearInterval(id); }, [loadApps, loadSettings, user]);
  useEffect(() => { if (!toast) return; const id = setTimeout(() => setToast(''), 3800); return () => clearTimeout(id); }, [toast]);
  const refresh = async () => { setBusy(true); try { const r = await apiFetch('/api/check', { method: 'POST' }); if (!r.ok) throw new Error(); const data = await r.json(); if (data.apps) setApps(data.apps); setLastUpdated(new Date(data.checkedAt)); setToast(data.started === false ? 'A health check is already in progress' : 'Health checks complete'); } catch { setToast('Unable to run health checks'); } finally { setBusy(false); } };
  const counts = useMemo(() => ({ up: apps.filter(a => a.status === 'up').length, down: apps.filter(a => a.status === 'down').length, unknown: apps.filter(a => a.status === 'unknown').length }), [apps]);
  const appLimit = Number(settingsData?.monitoring?.appLimit ?? 25);
  const filtered = apps.filter(a => `${a.name} ${a.url} ${a.group}`.toLowerCase().includes(search.toLowerCase()));
  const mapGroups = useMemo(() => (settingsData?.groups || []).flatMap(group => {
    const members = apps.filter(app => app.group === group.name);
    if (!members.length) return [];
    const points = members.map((app, index) => mapPosition(app, index));
    const minX = Math.min(...points.map(point => point.x)); const maxX = Math.max(...points.map(point => point.x));
    const minY = Math.min(...points.map(point => point.y)); const maxY = Math.max(...points.map(point => point.y));
    const left = Math.max(1, minX - 5); const top = Math.max(2, minY - 9);
    const right = Math.min(99, Math.max(maxX + 5, left + 15)); const bottom = Math.min(98, Math.max(maxY + 7, top + 18));
    return [{ ...group, members, left, top, width: right - left, height: bottom - top, centerX: points.reduce((sum, point) => sum + point.x, 0) / points.length, centerY: points.reduce((sum, point) => sum + point.y, 0) / points.length }];
  }), [apps, settingsData?.groups]);
  useEffect(() => { document.documentElement.dataset.theme = theme; try { localStorage.setItem('appwatch.theme', theme); } catch {} }, [theme]);
  const beginMapDrag = (event, app) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    dragRef.current = { kind: 'app', id: app.id, pointerId: event.pointerId, element: event.currentTarget, startX: event.clientX, startY: event.clientY, moved: false, original: { x: Number(app.x), y: Number(app.y) } };
  };
  const beginGroupDrag = (event, group) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    dragRef.current = { kind: 'group', groupId: group.id, appIds: group.members.map(app => app.id), pointerId: event.pointerId, element: event.currentTarget, startX: event.clientX, startY: event.clientY, moved: false, originals: group.members.map(app => ({ id: app.id, x: Number(app.x), y: Number(app.y) })) };
  };
  const mapCoordinates = (event, canvas) => {
    const rect = canvas.getBoundingClientRect();
    const xOffset = rect.width * (1 - mapZoom) / 2; const yOffset = rect.height * (1 - mapZoom) / 2;
    const x = ((event.clientX - rect.left - xOffset) / mapZoom / rect.width) * 100;
    const y = ((event.clientY - rect.top - yOffset) / mapZoom / rect.height) * 100;
    return { x: Math.round(Math.min(90, Math.max(8, x)) * 10) / 10, y: Math.round(Math.min(88, Math.max(10, y)) * 10) / 10 };
  };
  const moveMapNode = event => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    if (!drag.moved && Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) < 4) return;
    drag.moved = true;
    if (drag.kind === 'group') {
      const rect = event.currentTarget.getBoundingClientRect();
      const xs = drag.originals.map(point => point.x); const ys = drag.originals.map(point => point.y);
      const rawDx = (event.clientX - drag.startX) / mapZoom / rect.width * 100; const rawDy = (event.clientY - drag.startY) / mapZoom / rect.height * 100;
      const dx = Math.max(8 - Math.min(...xs), Math.min(90 - Math.max(...xs), rawDx));
      const dy = Math.max(10 - Math.min(...ys), Math.min(88 - Math.max(...ys), rawDy));
      drag.position = { dx: Math.round(dx * 10) / 10, dy: Math.round(dy * 10) / 10 };
      const positions = new Map(drag.originals.map(point => [point.id, { x: Math.round((point.x + drag.position.dx) * 10) / 10, y: Math.round((point.y + drag.position.dy) * 10) / 10 }]));
      setApps(current => current.map(app => positions.has(app.id) ? { ...app, ...positions.get(app.id) } : app));
      return;
    }
    drag.position = mapCoordinates(event, event.currentTarget);
    setApps(current => current.map(app => app.id === drag.id ? { ...app, ...drag.position } : app));
  };
  const finishMapNode = async event => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    if (!drag.moved) { dragRef.current = null; return; }
    if (drag.kind === 'group') moveMapNode(event);
    else { drag.position = mapCoordinates(event, event.currentTarget); setApps(current => current.map(app => app.id === drag.id ? { ...app, ...drag.position } : app)); }
    suppressMapClick.current = true;
    window.setTimeout(() => { suppressMapClick.current = false; }, 120);
    try {
      const response = drag.kind === 'group'
        ? await apiFetch(`/api/groups/${drag.groupId}/map-position`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(drag.position) })
        : await apiFetch(`/api/apps/${drag.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(drag.position) });
      const result = response.ok ? await response.json() : null;
      if (!response.ok) throw new Error(result?.error || 'Could not save this map position.');
      if (drag.kind === 'group') {
        const positions = new Map((result.positions || []).map(point => [point.id, point]));
        setApps(current => current.map(app => positions.has(app.id) ? { ...app, ...positions.get(app.id) } : app));
      } else setApps(current => current.map(app => app.id === drag.id ? { ...app, ...drag.position, ...(result || {}) } : app));
      setToast(drag.kind === 'group' ? 'Group position saved' : 'Map position saved');
    } catch (error) {
      const originals = drag.kind === 'group' ? new Map(drag.originals.map(point => [point.id, point])) : new Map([[drag.id, drag.original]]);
      setApps(current => current.map(app => originals.has(app.id) ? { ...app, ...originals.get(app.id) } : app));
      setToast(error.message || 'Could not save this map position');
    } finally {
      dragRef.current = null;
      try { drag.element.releasePointerCapture?.(drag.pointerId); } catch {}
    }
  };
  const toggleMapFullscreen = () => setMapFullscreen(value => !value);
  const setAndCloseTheme = value => { setTheme(value); setAccountMenuOpen(false); };
  const centerMap = () => { setMapZoom(1); setSelected(null); };
  useEffect(() => {
    if (!mapFullscreen) return undefined;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const onKeyDown = event => { if (event.key === 'Escape') setMapFullscreen(false); };
    window.addEventListener('keydown', onKeyDown);
    return () => { document.body.style.overflow = previousOverflow; window.removeEventListener('keydown', onKeyDown); };
  }, [mapFullscreen]);
  useEffect(() => {
    if (!notificationsOpen) return undefined;
    const onPointerDown = event => { if (!notificationsRef.current?.contains(event.target)) setNotificationsOpen(false); };
    const onKeyDown = event => { if (event.key === 'Escape') setNotificationsOpen(false); };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => { document.removeEventListener('pointerdown', onPointerDown); document.removeEventListener('keydown', onKeyDown); };
  }, [notificationsOpen]);
  useEffect(() => {
    if (!accountMenuOpen) return undefined;
    const onPointerDown = event => { if (!accountMenuRef.current?.contains(event.target)) setAccountMenuOpen(false); };
    const onKeyDown = event => { if (event.key === 'Escape') setAccountMenuOpen(false); };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => { document.removeEventListener('pointerdown', onPointerDown); document.removeEventListener('keydown', onKeyDown); };
  }, [accountMenuOpen]);
  const saveApp = async values => {
    const editing = modal?.mode === 'edit'; const url = editing ? `/api/apps/${modal.app.id}` : '/api/apps';
    const r = await apiFetch(url, { method: editing ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(values) }); const data = r.status === 204 ? null : await r.json();
    if (!r.ok) throw new Error(data?.error || 'Could not save application'); setModal(null); await loadApps(); await loadSettings(); setToast(editing ? 'Application updated' : 'Application added');
  };
  const removeApp = async id => { if (!window.confirm('Remove this application from monitoring?')) return; const r = await apiFetch(`/api/apps/${id}`, { method: 'DELETE' }); if (!r.ok) return setToast('Could not remove application'); setApps(v => v.filter(a => a.id !== id)); await loadSettings(); setSelected(null); setToast('Application removed'); };
    const settingsRequest = async (path, values, successMessage) => { const r = await apiFetch(`/api${path}`, { method: path.includes('test-alert') ? 'POST' : 'PUT', headers: { 'Content-Type': 'application/json' }, ...(path.includes('test-alert') ? {} : { body: JSON.stringify(values) }) }); const data = r.status === 204 ? null : await r.json(); if (!r.ok) throw new Error(data?.error || 'Could not save settings'); if (path === '/settings/profile' && data.emailVerificationRequired) { setUser(null); setAuthMode('login'); setAuthNotice(data.message); setToast('Check your new email address to finish the change'); return data; } if (path === '/settings/profile') setUser(data.profile); if (!path.includes('test-alert')) await loadSettings(); setToast(successMessage); return data; };
  const groupRequest = async (path, method, values, successMessage) => { const r = await apiFetch(`/api${path}`, { method, headers: values ? { 'Content-Type': 'application/json' } : undefined, body: values ? JSON.stringify(values) : undefined }); const data = r.status === 204 ? null : await r.json(); if (!r.ok) throw new Error(data?.error || 'Could not update groups'); await Promise.all([loadSettings(), loadApps()]); setToast(successMessage); return data; };
  const authenticate = async values => {
    setAuthError(''); setAuthNotice('');
    const endpoints = { signup: 'signup', login: 'login', forgot: 'forgot-password', reset: 'reset-password' };
    try {
      const r = await apiFetch(`/api/auth/${endpoints[authMode]}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(authMode === 'reset' ? { token: resetToken, newPassword: values.newPassword } : values) });
      const data = await r.json(); if (!r.ok) throw new Error(data.error || 'Unable to continue');
      if (authMode === 'login') { setUser(data.user); return; }
      setAuthNotice(data.message || 'Request complete.'); setAuthMode('login'); setResetToken('');
    } catch (error) { setAuthError(error.message || 'Unable to connect to the backend.'); throw error; }
  };
  const resendVerification = async email => { setAuthError(''); try { const r = await apiFetch('/api/auth/resend-verification', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email }) }); const data = await r.json(); if (!r.ok) throw new Error(data.error); setAuthNotice(data.message); } catch (error) { setAuthError(error.message || 'Unable to resend verification.'); } };
  const logout = async () => { await apiFetch('/api/auth/logout', { method: 'POST' }).catch(() => {}); setUser(null); setApps([]); };
  const nav = [{ name: 'Overview', icon: LayoutDashboard }, { name: 'Network map', icon: MapIcon }, { name: 'Applications', icon: Server }];
  if (authLoading) return <div className="auth-loading"><LoaderCircle size={22} className="spin"/><span>Connecting to AppWatch…</span></div>;
  if (!user) return <AuthScreen mode={authMode} resetToken={resetToken} setMode={mode => { setAuthMode(mode); setAuthError(''); setAuthNotice(''); }} onSubmit={authenticate} onResend={resendVerification} error={authError} notice={authNotice}/>;
  return <div className="shell">
    <aside className="sidebar">
      <div className="brand"><span className="brand-mark"><Activity size={19}/></span><span>app<span className="brand-accent">watch</span></span><span className="brand-version">v1.0</span></div>
      <div className="workspace-label">WORKSPACE</div><div className="workspace-switch workspace-static"><span className="workspace-icon">{initials(user.name)[0]}</span><span className="workspace-copy"><b>{user.name}’s workspace</b><small>Personal workspace</small></span></div>
      <div className="nav-label">MONITORING</div><nav>{nav.map(item => <button key={item.name} className={`nav-item ${page === item.name ? 'active' : ''}`} onClick={() => setPage(item.name)}><item.icon size={17}/>{item.name}{item.name === 'Applications' && <span className="nav-count">{apps.length}</span>}{item.name === 'Network map' && counts.down > 0 && <span className="nav-alert"/>}</button>)}</nav>
      <div className="nav-label groups-label">GROUPS <button onClick={() => setPage('Settings')} title="Manage groups"><Plus size={14}/></button></div>
      <div className="group-links">{(settingsData?.groups || []).map((g, i) => <button key={g.id} className="group-link" onClick={() => { setPage('Applications'); setSearch(g.name); }}><i className={`group-dot dot-${i % 4}`} style={{ background: g.color }}/>{g.name}<span>{g.appCount}</span></button>)}</div>
      <div className="sidebar-bottom"><div className="plan-card"><div className="plan-head"><span>MONITORING LIMIT</span><Zap size={14}/></div><div className="plan-total"><b>{apps.length}</b><span>/ {appLimit} apps</span></div><div className="progress-track"><span style={{ width: `${Math.min(apps.length / appLimit * 100, 100)}%` }}/></div><div className="plan-sub">{apps.length} of {appLimit} available slots used</div></div><button className={`nav-item settings ${page === 'Settings' ? 'active' : ''}`} onClick={() => setPage('Settings')}><Settings2 size={17}/>Settings</button><div className="profile"><div className="avatar">{initials(user.name)}</div><div className="profile-info"><b>{user.name}</b><small>{user.email}</small></div><button className="profile-logout" onClick={logout} title="Sign out"><LogOut size={16}/></button></div></div>
    </aside>
    <main className="main">
      <header className="topbar"><div className="breadcrumbs"><span>Workspace</span><span className="crumb-slash">/</span><b>{page === 'Overview' ? 'Overview' : page}</b></div><div className="top-actions"><div className={`live-indicator ${counts.down ? 'has-down' : ''}`}><i/> {counts.down ? `${counts.down} application${counts.down > 1 ? 's' : ''} down` : counts.unknown ? 'Checks initializing' : apps.length ? 'All systems operational' : 'No apps monitored'}</div><div className="notification-wrap" ref={notificationsRef}><button className="icon-button notification" aria-label="Open application alerts" aria-expanded={notificationsOpen} onClick={() => setNotificationsOpen(value => !value)}><Bell size={18}/>{counts.down > 0 && <i/>}</button>{notificationsOpen && <div className="notifications-popover"><div className="notifications-heading"><b>Application alerts</b><span>{counts.down} down</span></div>{apps.filter(app => app.status === 'down').length ? apps.filter(app => app.status === 'down').map(app => <button className="notification-row" key={app.id} onClick={() => { setPage('Applications'); setSearch(app.name); setNotificationsOpen(false); }}><span className="notification-dot"/><span><b>{app.name}</b><small>{app.error || 'Endpoint is unreachable'}</small></span><ArrowUpRight size={14}/></button>) : <div className="notifications-empty"><Check size={15}/>No applications are currently down.</div>}</div>}</div><span className="top-divider"/><div className="account-menu-wrap" ref={accountMenuRef}><button className="avatar top-avatar account-menu-trigger" aria-label="Open account settings menu" aria-expanded={accountMenuOpen} onClick={() => setAccountMenuOpen(value => !value)}>{initials(user.name)}<ChevronDown size={12}/></button>{accountMenuOpen && <div className="account-menu"><div className="account-menu-identity"><span className="avatar">{initials(user.name)}</span><span><b>{user.name}</b><small>{user.email}</small></span></div><button className="account-menu-item" onClick={() => { setPage('Settings'); setAccountMenuOpen(false); }}><Settings2 size={15}/>Account settings</button><div className="account-menu-theme"><span><Sun size={15}/>Appearance</span><div><button className={theme === 'light' ? 'active' : ''} onClick={() => setAndCloseTheme('light')} aria-label="Use light theme"><Sun size={14}/></button><button className={theme === 'dark' ? 'active' : ''} onClick={() => setAndCloseTheme('dark')} aria-label="Use dark theme"><Moon size={14}/></button></div></div><button className="account-menu-item sign-out" onClick={() => { setAccountMenuOpen(false); logout(); }}><LogOut size={15}/>Sign out</button></div>}</div></div></header>
      <div className="content">
        <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line"/> {page === 'Settings' ? 'ACCOUNT & PREFERENCES' : 'LIVE MONITORING'}</div><h1>{page === 'Overview' ? `Good morning, ${user.name.split(/\s+/)[0]}` : page}</h1><p>{page === 'Overview' ? 'Here’s what’s happening across your applications.' : page === 'Network map' ? 'A live view of your application infrastructure.' : page === 'Settings' ? 'Manage your account, monitoring schedule, alerts, and groups.' : 'Manage the applications and endpoints you monitor.'}</p></div>{page !== 'Settings' && <div className="heading-actions"><span className="updated-label"><Clock3 size={14}/> Updated {lastUpdated ? lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'}</span><button className="button-secondary" onClick={refresh} disabled={busy}>{busy ? <LoaderCircle className="spin" size={16}/> : <RefreshCw size={15}/>}Refresh</button><button className="button-primary" onClick={() => setModal({ mode: 'add' })}><Plus size={17}/> Add application</button></div>}</div>
        {page === 'Overview' && <section className="stats-grid"><StatCard label="Total applications" value={apps.length} icon={<Globe2/>} detail="Across all groups" tone="blue"/><StatCard label="Online" value={counts.up} icon={<ArrowUpRight/>} detail={apps.length ? `${Math.round(counts.up / apps.length * 100)}% uptime right now` : 'Waiting for first check'} tone="green"/><StatCard label="Down" value={counts.down} icon={<ArrowDownRight/>} detail={counts.down ? 'Needs your attention' : 'Everything looks good'} tone={counts.down ? 'red' : 'slate'}/><StatCard label="Avg. response time" value={`${apps.filter(a => a.latency !== null).length ? Math.round(apps.filter(a => a.latency !== null).reduce((s,a) => s + a.latency,0) / apps.filter(a => a.latency !== null).length) : '—'}${apps.some(a => a.latency !== null) ? ' ms' : ''}`} icon={<Activity/>} detail="Across checked endpoints" tone="purple"/></section>}
        {(page === 'Overview' || page === 'Network map') && <section className={`map-section ${mapFullscreen ? 'map-fullscreen' : ''}`}>
          <div className="section-header"><div><h2>Network map <span className="live-tag"><i/>LIVE</span></h2><p>Drag a group label to move its apps together, or drag an app to move it on its own.</p></div><div className="map-actions"><div className="map-legend"><span><i className="legend-up"/>Online <b>{counts.up}</b></span><span><i className="legend-down"/>Down <b>{counts.down}</b></span><span><i className="legend-unknown"/>Pending <b>{counts.unknown}</b></span></div><button className="map-link" onClick={() => page === 'Network map' ? toggleMapFullscreen() : setPage('Network map')}>{page === 'Network map' ? mapFullscreen ? 'Exit full view' : 'Full map' : 'Open map'}{page === 'Network map' ? mapFullscreen ? <Minimize2 size={14}/> : <Maximize2 size={14}/> : <ExternalLink size={13}/>}</button></div></div>
          <div className={`map-canvas ${page === 'Network map' ? 'map-expanded' : ''} ${mapFullscreen ? 'map-canvas-fullscreen' : ''}`} onPointerMove={moveMapNode} onPointerUp={finishMapNode} onPointerCancel={finishMapNode}>
            <div className="map-world" style={{ transform: `scale(${mapZoom})` }}>
              <div className="map-grid"/><div className="map-watermark">{user.name.toUpperCase()} <span>·</span> LIVE TOPOLOGY</div>
              <svg className="connections" viewBox="0 0 1000 500" preserveAspectRatio="none"><defs><linearGradient id="lineGlow"><stop stopColor="#475569" stopOpacity=".14"/><stop offset=".5" stopColor="#60a5fa" stopOpacity=".34"/><stop offset="1" stopColor="#475569" stopOpacity=".14"/></linearGradient></defs>{apps.map((app, index) => { const point = mapPosition(app, index); const x = point.x * 10; const y = point.y * 5; return <g key={app.id}><path d={`M 500 250 Q ${500 + (x - 500) * .45} ${250 + (y - 250) * .15} ${x} ${y}`}/><path className="path-dash" d={`M 500 250 Q ${500 + (x - 500) * .45} ${250 + (y - 250) * .15} ${x} ${y}`}/></g>; })}<circle className="map-hub-ring" cx="500" cy="250" r="13"/><circle className="map-hub" cx="500" cy="250" r="5"/><text className="map-hub-label" x="500" y="276">APPWATCH PROBE</text></svg>
              {mapGroups.map(group => <div key={group.id} className="map-group-region" style={{ left: `${group.left}%`, top: `${group.top}%`, width: `${group.width}%`, height: `${group.height}%`, '--group-color': group.color }}><button type="button" className={`map-group-handle ${dragRef.current?.groupId === group.id && dragRef.current?.moved ? 'dragging' : ''}`} onPointerDown={event => beginGroupDrag(event, group)} aria-label={`Move ${group.name} group and its ${group.members.length} applications`}><GripVertical size={13}/><span>{group.name}</span><small>{group.members.length}</small></button></div>)}
              <div className="region-label label-prod">PRODUCTION <span/></div><div className="region-label label-edge">EDGE NETWORK <span/></div>
              {apps.map((app, index) => { const point = mapPosition(app, index); return <MapNode key={app.id} app={app} selected={selected === app.id} onClick={() => { if (suppressMapClick.current) { suppressMapClick.current = false; return; } setSelected(selected === app.id ? null : app.id); }} onPointerDown={event => beginMapDrag(event, app)} dragging={dragRef.current?.id === app.id && dragRef.current?.moved} style={{ left: `${point.x}%`, top: `${point.y}%` }}/>; })}
              {apps.length === 0 && <div className="map-empty-state"><div><Server size={21}/></div><b>No applications on the map</b><span>Add an endpoint to see its live status here.</span><button className="button-primary" onClick={() => setModal({ mode: 'add' })}><Plus size={14}/>Add application</button></div>}
            </div>
            {selected && apps.find(app => app.id === selected) && <NodePopover app={apps.find(app => app.id === selected)} onEdit={() => setModal({ mode: 'edit', app: apps.find(app => app.id === selected) })} onClose={() => setSelected(null)}/>}
            <div className="map-controls"><button onClick={() => setMapZoom(zoom => Math.min(2, Number((zoom + .2).toFixed(1))))} title="Zoom in"><ZoomIn size={15}/></button><button onClick={() => setMapZoom(zoom => Math.max(.8, Number((zoom - .2).toFixed(1))))} title="Zoom out"><ZoomOut size={15}/></button><span/><button onClick={centerMap} title="Reset zoom and center the map"><LocateFixed size={15}/></button></div><div className="map-attribution"><span/> {lastUpdated ? `Updated ${lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : 'Waiting for first check'} <b>{Math.round(mapZoom * 100)}%</b></div>
          </div><div className="map-foot"><span><Signal size={13}/> Checks every {settingsData?.monitoring?.checkIntervalSeconds ?? 60} seconds</span><span>Drag a group or app · click an app to inspect</span></div></section>}
        {page === 'Overview' && <section className="bottom-grid"><div className="panel activity-panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Latest events across your apps</p></div><button className="text-button" onClick={() => setPage('Applications')}>View all <span>→</span></button></div>{apps.slice().sort((a,b) => (b.checkedAt || '').localeCompare(a.checkedAt || '')).slice(0,4).map(a => <ActivityRow key={a.id} app={a}/>)}{apps.length === 0 && <EmptyState onAdd={() => setModal({ mode: 'add' })}/>}</div><div className="panel uptime-panel"><div className="panel-heading"><div><h2>Recent availability</h2><p>Based on your latest saved checks</p></div><span className="period-label">Latest checks</span></div><div className="uptime-list">{apps.slice(0,4).map(app => <UptimeRow key={app.id} app={app}/>)}</div><div className="uptime-axis"><span>Oldest saved check</span><span>Latest</span></div></div></section>}
        {page === 'Applications' && <section className="panel applications-panel"><div className="panel-heading"><div><h2>All applications <span className="count-chip">{apps.length}</span></h2><p>Manage your monitored endpoints and checks</p></div><div className="list-actions"><div className="search-box"><Search size={15}/><input placeholder="Search applications..." value={search} onChange={e => setSearch(e.target.value)}/>{search && <button onClick={() => setSearch('')}><X size={13}/></button>}</div><button className="button-secondary" onClick={refresh} disabled={busy}>{busy ? <LoaderCircle size={15} className="spin"/> : <RefreshCw size={15}/>}Check now</button></div></div><div className="table-wrap"><table><thead><tr><th>APPLICATION</th><th>GROUP</th><th>STATUS</th><th>RESPONSE</th><th>LAST CHECK</th><th/></tr></thead><tbody>{filtered.map(a => <tr key={a.id}><td><div className="app-cell"><span className={`service-avatar ${a.status}`}>{initials(a.name)}</span><div><b>{a.name}</b><small>{hostOf(a.url)}</small></div></div></td><td><span className="group-pill"><i style={{ background: settingsData?.groups?.find(g => g.name === a.group)?.color || undefined }}/>{a.group}</span></td><td><StatusBadge status={a.status}/></td><td className="latency-cell">{a.latency === null ? '—' : `${a.latency} ms`}</td><td className="time-cell">{fmtTime(a.checkedAt)}</td><td><div className="row-actions"><a href={a.url} target="_blank" rel="noreferrer" title="Open endpoint"><ExternalLink size={15}/></a><button onClick={() => setModal({ mode: 'edit', app: a })} title="Edit"><Settings2 size={15}/></button><button onClick={() => removeApp(a.id)} title="Remove"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table>{filtered.length === 0 && <div className="empty-table">{apps.length ? 'No applications match your search.' : <EmptyState onAdd={() => setModal({ mode: 'add' })}/>}</div>}</div><div className="table-footer"><span>Showing <b>{filtered.length}</b> of <b>{apps.length}</b> applications</span><span><i className="green-pulse"/> Auto-checking every {settingsData?.monitoring?.checkIntervalSeconds ?? 60} seconds</span></div></section>}
        {page === 'Settings' && (settingsData ? <SettingsPage data={settingsData} onSave={settingsRequest} onGroupRequest={groupRequest} theme={theme} onThemeChange={setTheme}/> : <div className="settings-loading"><LoaderCircle className="spin" size={18}/>Loading settings…</div>)}
        <footer className="footer"><span>© 2026 AppWatch</span><span className={`footer-health ${counts.down ? 'down' : counts.unknown || !apps.length ? 'pending' : ''}`}><span className="footer-status"/><ShieldCheck size={13}/>{counts.down ? `${counts.down} application${counts.down === 1 ? ' is' : 's are'} down` : counts.unknown ? 'Checks initializing' : apps.length ? 'All systems operational' : 'No apps monitored'}</span><span>Built for reliability <span className="heart">♥</span></span></footer>
      </div>
    </main>
    {modal && <AppModal modal={modal} groups={settingsData?.groups || []} onClose={() => setModal(null)} onSave={saveApp}/>}
    {toast && <div className="toast"><Check size={16}/>{toast}<button onClick={() => setToast('')}><X size={15}/></button></div>}
  </div>;
}

function StatCard({ label, value, icon, detail, tone }) { return <div className="stat-card"><div className={`stat-icon ${tone}`}>{icon}</div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-detail">{tone === 'red' && value > 0 ? <AlertTriangle size={12}/> : null}{detail}</div><div className={`stat-decoration ${tone}`}/></div>; }
function StatusBadge({ status }) { return <span className={`status-badge ${status}`}><i/>{status === 'up' ? 'Online' : status === 'down' ? 'Down' : 'Checking'}</span>; }
function MapNode({ app, style, selected, onClick, onPointerDown, dragging }) { const state = app.status || 'unknown'; return <button className={`map-node ${state} ${selected ? 'selected' : ''} ${dragging ? 'dragging' : ''}`} style={style} onClick={onClick} onPointerDown={onPointerDown} aria-label={`${app.name}, ${state}. Drag to reposition, click to inspect.`}><span className="node-halo"/><span className="node-core"><Server size={16}/></span><span className="node-copy"><b>{app.name}</b><small><i/> {state === 'up' ? `${app.latency ?? '—'} ms` : state === 'down' ? 'Unreachable' : 'Waiting for check'}</small></span><span className="node-indicator"/></button>; }
function NodePopover({ app, onEdit, onClose }) { return <div className="node-popover"><button className="popover-close" onClick={onClose}><X size={13}/></button><div className="popover-head"><span className={`service-avatar ${app.status}`}>{initials(app.name)}</span><div><b>{app.name}</b><small>{app.group}</small></div></div><div className="popover-url">{hostOf(app.url)}</div><div className="popover-line"><StatusBadge status={app.status}/><span>{app.latency === null ? '—' : `${app.latency} ms`}</span></div><button className="popover-edit" onClick={onEdit}>Manage application <ExternalLink size={13}/></button></div>; }
function ActivityRow({ app }) { return <div className="activity-row"><span className={`activity-marker ${app.status}`}>{app.status === 'down' ? <ArrowDownRight size={13}/> : app.status === 'up' ? <Check size={12}/> : <Clock3 size={12}/>}</span><span className="activity-copy"><b>{app.name}</b><small>{app.status === 'up' ? 'is responding normally' : app.status === 'down' ? `is unreachable · ${app.error || 'connection failed'}` : 'waiting for first health check'}</small></span><span className={`activity-status ${app.status}`}>{app.status === 'up' ? 'Online' : app.status === 'down' ? 'Down' : 'Pending'}</span><span className="activity-time">{app.checkedAt ? fmtTime(app.checkedAt) : '—'}</span></div>; }
function UptimeRow({ app }) { const samples = (app.history || []).filter(item => item.status === 'up' || item.status === 'down').slice(-18); const bars = samples.length ? samples : Array.from({ length: 18 }, () => ({ status: 'unknown' })); const uptime = samples.length ? Math.round(samples.filter(item => item.status === 'up').length / samples.length * 100) : null; return <div className="uptime-row"><span className={`service-avatar ${app.status}`}>{initials(app.name)}</span><div className="uptime-name"><b>{app.name}</b><div className="uptime-bars" title={`${samples.length} saved checks`}>{bars.map((item, index) => <i key={index} className={item.status}/>)}</div></div><span className={`uptime-percent ${uptime !== null && uptime < 100 ? 'red-text' : ''}`}>{uptime === null ? '—' : `${uptime}%`}</span></div>; }
function EmptyState({ onAdd }) { return <div className="empty-state"><div><Server size={21}/></div><b>No applications yet</b><span>Add an endpoint to start monitoring its availability.</span><button className="button-primary" onClick={onAdd}><Plus size={15}/>Add application</button></div>; }
function AuthScreen({ mode, resetToken, setMode, onSubmit, onResend, error, notice }) {
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [busy, setBusy] = useState(false); const [formError, setFormError] = useState('');
  const signup = mode === 'signup'; const forgot = mode === 'forgot'; const reset = mode === 'reset';
  const title = signup ? 'Create your account' : forgot ? 'Reset your password' : reset ? 'Choose a new password' : 'Welcome back';
  const description = signup ? 'Create an account to monitor your applications.' : forgot ? 'We’ll email a password-reset link if the account exists.' : reset ? 'Choose a new password for your AppWatch account.' : 'Sign in to continue to your monitoring dashboard.';
  const submit = async event => {
    event.preventDefault(); setFormError('');
    if (reset && password !== confirm) { setFormError('The new passwords do not match.'); return; }
    setBusy(true);
    try { await onSubmit(signup ? { name, email, password } : reset ? { newPassword: password } : forgot ? { email } : { email, password }); }
    catch {} finally { setBusy(false); }
  };
  return <div className="auth-page"><div className="auth-orb orb-one"/><div className="auth-orb orb-two"/><div className="auth-brand"><span className="brand-mark"><Activity size={19}/></span><span>app<span className="brand-accent">watch</span></span></div><form className="auth-card" onSubmit={submit}><div className="auth-kicker">LIVE APPLICATION MONITORING</div><h1>{title}</h1><p>{description}</p>{notice && <div className="auth-notice"><Check size={14}/>{notice}</div>}{signup && <label>Full name<input autoComplete="name" value={name} onChange={e => setName(e.target.value)} placeholder="Your name" required maxLength={80}/></label>}{!reset && <label>Email address<input autoComplete="email" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@company.com" required/></label>}{!forgot && !reset && <label>Password<input autoComplete={signup ? 'new-password' : 'current-password'} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder={signup ? 'At least 8 characters' : 'Your password'} required minLength={signup ? 8 : undefined} maxLength={72}/></label>}{reset && <><label>New password<input autoComplete="new-password" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 8 characters" required minLength={8} maxLength={72}/></label><label>Confirm new password<input autoComplete="new-password" type="password" value={confirm} onChange={e => setConfirm(e.target.value)} required minLength={8} maxLength={72}/></label></>}{(error || formError) && <div className="auth-error"><AlertTriangle size={14}/>{formError || error}</div>}{error?.toLowerCase().includes('verify your email') && <button className="auth-inline-link" type="button" disabled={busy} onClick={() => onResend(email)}>Resend verification email</button>}<button className="button-primary auth-submit" disabled={busy}>{busy && <LoaderCircle size={15} className="spin"/>}{signup ? 'Create account' : forgot ? 'Send reset link' : reset ? 'Update password' : 'Sign in'}</button>{mode === 'login' && <button className="auth-inline-link forgot-link" type="button" onClick={() => setMode('forgot')}>Forgot password?</button>}<div className="auth-switch">{signup ? 'Already have an account?' : forgot || reset ? 'Remembered your password?' : 'New to AppWatch?'} <button type="button" onClick={() => setMode(signup || forgot || reset ? 'login' : 'signup')}>{signup || forgot || reset ? 'Sign in' : 'Create account'}</button></div></form><div className="auth-caption"><span className="footer-status"/>Your apps. One clear picture.</div></div>;
}
function SettingsPage({ data, onSave, onGroupRequest, theme, onThemeChange }) {
  const [name, setName] = useState(data.profile.name); const [email, setEmail] = useState(data.profile.email);
  const [interval, setInterval] = useState(String(data.monitoring.checkIntervalSeconds)); const [timeout, setTimeout] = useState(String(data.monitoring.timeoutSeconds));
  const [appLimit, setAppLimit] = useState(String(data.monitoring.appLimit ?? 25));
  const [emailAlerts, setEmailAlerts] = useState(data.notifications.emailAlerts); const [alertEmail, setAlertEmail] = useState(data.notifications.alertEmail || data.profile.email);
  const [alertOnDown, setAlertOnDown] = useState(data.notifications.alertOnDown); const [alertOnRecovery, setAlertOnRecovery] = useState(data.notifications.alertOnRecovery);
  const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [confirmPassword, setConfirmPassword] = useState('');
  const [groupName, setGroupName] = useState(''); const [groupColor, setGroupColor] = useState('#6d8df4'); const [error, setError] = useState(''); const [pending, setPending] = useState('');
  const currentAppCount = data.groups.reduce((total, group) => total + group.appCount, 0);
  useEffect(() => { setName(data.profile.name); setEmail(data.profile.email); setInterval(String(data.monitoring.checkIntervalSeconds)); setTimeout(String(data.monitoring.timeoutSeconds)); setAppLimit(String(data.monitoring.appLimit ?? 25)); setEmailAlerts(data.notifications.emailAlerts); setAlertEmail(data.notifications.alertEmail || data.profile.email); setAlertOnDown(data.notifications.alertOnDown); setAlertOnRecovery(data.notifications.alertOnRecovery); }, [data]);
  const run = async (key, callback) => { setError(''); setPending(key); try { await callback(); } catch (err) { setError(err.message || 'Something went wrong.'); } finally { setPending(''); } };
  const saveProfile = e => { e.preventDefault(); run('profile', () => onSave('/settings/profile', { name, email }, 'Profile updated')); };
  const savePassword = e => { e.preventDefault(); if (newPassword !== confirmPassword) { setError('The new passwords do not match.'); return; } run('password', async () => { await onSave('/settings/password', { currentPassword, newPassword }, 'Password changed'); setCurrentPassword(''); setNewPassword(''); setConfirmPassword(''); }); };
  const saveMonitoring = e => { e.preventDefault(); run('monitoring', () => onSave('/settings/monitoring', { checkIntervalSeconds: Number(interval), timeoutSeconds: Number(timeout), appLimit: Number(appLimit) }, 'Monitoring settings saved')); };
  const saveNotifications = e => { e.preventDefault(); run('notifications', () => onSave('/settings/notifications', { emailAlerts, alertEmail, alertOnDown, alertOnRecovery }, 'Alert preferences saved')); };
  const addGroup = e => { e.preventDefault(); run('new-group', async () => { await onGroupRequest('/groups', 'POST', { name: groupName, color: groupColor }, 'Group created'); setGroupName(''); }); };
  return <div className="settings-page">
    {error && <div className="settings-global-error"><AlertTriangle size={15}/>{error}<button onClick={() => setError('')}><X size={14}/></button></div>}
    <section className="settings-card appearance-card"><div className="settings-card-head"><span className="settings-icon purple">{theme === 'dark' ? <Moon size={17}/> : <Sun size={17}/>}</span><div><h2>Appearance</h2><p>Choose the theme used across your AppWatch workspace.</p></div></div><div className="theme-choice-row"><button type="button" className={theme === 'light' ? 'active' : ''} aria-pressed={theme === 'light'} onClick={() => onThemeChange('light')}><Sun size={17}/><span><b>Light</b><small>Bright surfaces and clear borders</small></span>{theme === 'light' && <Check size={16}/>}</button><button type="button" className={theme === 'dark' ? 'active' : ''} aria-pressed={theme === 'dark'} onClick={() => onThemeChange('dark')}><Moon size={17}/><span><b>Dark</b><small>Low-glare dark surfaces</small></span>{theme === 'dark' && <Check size={16}/>}</button></div></section>
    <form className="settings-card" onSubmit={saveProfile}><div className="settings-card-head"><span className="settings-icon"><UserRound size={17}/></span><div><h2>Profile</h2><p>Update the name and email on your account.</p></div></div><div className="settings-form-grid"><label>Full name<input value={name} onChange={e => setName(e.target.value)} required maxLength={80}/></label><label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} required maxLength={254}/></label></div><div className="settings-card-foot"><span>Your email is also used as the default alert address.</span><button className="button-primary" disabled={pending === 'profile'}>{pending === 'profile' ? <LoaderCircle size={14} className="spin"/> : <Save size={14}/>}Save profile</button></div></form>
    <form className="settings-card" onSubmit={savePassword}><div className="settings-card-head"><span className="settings-icon purple"><KeyRound size={17}/></span><div><h2>Password</h2><p>Change your password. Use at least 8 characters.</p></div></div><div className="settings-form-grid three"><label>Current password<input type="password" autoComplete="current-password" value={currentPassword} onChange={e => setCurrentPassword(e.target.value)} required/></label><label>New password<input type="password" autoComplete="new-password" value={newPassword} onChange={e => setNewPassword(e.target.value)} required minLength={8} maxLength={72}/></label><label>Confirm new password<input type="password" autoComplete="new-password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required minLength={8} maxLength={72}/></label></div><div className="settings-card-foot"><span>Password changes take effect immediately.</span><button className="button-primary" disabled={pending === 'password'}>{pending === 'password' ? <LoaderCircle size={14} className="spin"/> : <KeyRound size={14}/>}Change password</button></div></form>
    <form className="settings-card" onSubmit={saveMonitoring}><div className="settings-card-head"><span className="settings-icon blue"><SlidersHorizontal size={17}/></span><div><h2>Monitoring defaults</h2><p>Set how often checks run, how long they wait, and your account’s app capacity.</p></div></div><div className="settings-form-grid three"><label>Check interval<select value={interval} onChange={e => setInterval(e.target.value)}>{[30,60,120,300,600,900,1800,3600].map(value => <option key={value} value={value}>{value < 60 ? `${value} seconds` : `${value / 60} minute${value === 60 ? '' : 's'}`}</option>)}</select><small>How often all apps are checked.</small></label><label>Request timeout<select value={timeout} onChange={e => setTimeout(e.target.value)}>{[2,3,5,8,10,15,30,60].map(value => <option key={value} value={value}>{value} seconds</option>)}</select><small>Maximum wait for each endpoint.</small></label><label>Application limit<input type="number" min={Math.max(1, currentAppCount)} max="1000" step="1" value={appLimit} onChange={e => setAppLimit(e.target.value)} required/><small>Between {currentAppCount || 1} and 1,000 apps. Current: {currentAppCount}.</small></label></div><div className="settings-card-foot"><span>Limit changes apply to new applications. Existing apps are kept.</span><button className="button-primary" disabled={pending === 'monitoring'}>{pending === 'monitoring' ? <LoaderCircle size={14} className="spin"/> : <Save size={14}/>}Save monitoring</button></div></form>
    <form className="settings-card" onSubmit={saveNotifications}><div className="settings-card-head"><span className="settings-icon amber"><Mail size={17}/></span><div><h2>Email alerts</h2><p>Get notified when an app goes down and when it recovers.</p></div><span className={`delivery-chip ${data.emailDeliveryConfigured ? 'ready' : ''}`}><i/>{data.emailDeliveryConfigured ? 'Email configured' : 'Email not configured'}</span></div><div className="settings-toggle-row"><div><b>Enable email notifications</b><small>Send alerts to the address below.</small></div><Toggle checked={emailAlerts} onChange={setEmailAlerts}/></div><label className="settings-email-field">Alert email<input type="email" value={alertEmail} onChange={e => setAlertEmail(e.target.value)} required maxLength={254}/><small>Defaults to your account email, but can be changed.</small></label><div className="settings-checks"><label><input type="checkbox" checked={alertOnDown} onChange={e => setAlertOnDown(e.target.checked)}/> Notify when an app goes down</label><label><input type="checkbox" checked={alertOnRecovery} onChange={e => setAlertOnRecovery(e.target.checked)}/> Notify when an app recovers</label></div><div className="settings-card-foot"><span>Alerts are sent only when status changes.</span><div className="settings-action-row"><button type="button" className="button-secondary" disabled={!data.emailDeliveryConfigured || pending === 'test'} onClick={() => run('test', async () => { const values = { emailAlerts, alertEmail, alertOnDown, alertOnRecovery }; await onSave('/settings/notifications', values, 'Alert preferences saved'); await onSave('/settings/test-alert', null, 'Test email sent'); })}>{pending === 'test' ? <LoaderCircle size={14} className="spin"/> : <Send size={14}/>}Send test email</button><button className="button-primary" disabled={pending === 'notifications'}>{pending === 'notifications' ? <LoaderCircle size={14} className="spin"/> : <Save size={14}/>}Save alert preferences</button></div></div></form>
    <section className="settings-card"><div className="settings-card-head"><span className="settings-icon green"><FolderKanban size={17}/></span><div><h2>Application groups</h2><p>Organize apps on your dashboard and map. Deleting a group moves its apps to Unassigned.</p></div></div><div className="group-manager">{data.groups.map(group => <GroupRow key={group.id} group={group} pending={pending} run={run} onRequest={onGroupRequest}/>)}</div><form className="group-add-row" onSubmit={addGroup}><input type="color" value={groupColor} onChange={e => setGroupColor(e.target.value)} aria-label="New group color"/><input value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="New group name" required maxLength={40}/><button className="button-primary" disabled={pending === 'new-group'}>{pending === 'new-group' ? <LoaderCircle size={14} className="spin"/> : <Plus size={14}/>}Add group</button></form></section>
  </div>;
}
function Toggle({ checked, onChange }) { return <button type="button" role="switch" aria-checked={checked} className={`settings-toggle ${checked ? 'on' : ''}`} onClick={() => onChange(!checked)}><span/></button>; }
function GroupRow({ group, pending, run, onRequest }) {
  const [name, setName] = useState(group.name); const [color, setColor] = useState(group.color);
  useEffect(() => { setName(group.name); setColor(group.color); }, [group.name, group.color]);
  const save = () => run(`group-${group.id}`, () => onRequest(`/groups/${group.id}`, 'PUT', { name, color }, 'Group updated'));
  const remove = () => { if (group.name === 'Unassigned' || !window.confirm(`Delete “${group.name}”? Apps in this group will move to Unassigned.`)) return; run(`group-${group.id}`, () => onRequest(`/groups/${group.id}`, 'DELETE', null, 'Group deleted')); };
  return <div className="group-manager-row"><input type="color" value={color} onChange={e => setColor(e.target.value)} aria-label={`${group.name} color`}/><input value={name} onChange={e => setName(e.target.value)} maxLength={40} aria-label="Group name"/><span>{group.appCount} app{group.appCount === 1 ? '' : 's'}</span><button type="button" className="group-save" onClick={save} disabled={pending === `group-${group.id}`} title="Save group">{pending === `group-${group.id}` ? <LoaderCircle size={14} className="spin"/> : <Save size={14}/>}</button><button type="button" className="group-delete" onClick={remove} disabled={group.name === 'Unassigned' || pending === `group-${group.id}`} title={group.name === 'Unassigned' ? 'This group is required' : 'Delete group'}><Trash2 size={14}/></button></div>;
}
function AppModal({ modal, groups, onClose, onSave }) { const editing = modal.mode === 'edit'; const app = modal.app || {}; const initialGroup = app.group || groups[0]?.name || 'Unassigned'; const [name, setName] = useState(app.name || ''); const [url, setUrl] = useState(app.url || ''); const [group, setGroup] = useState(initialGroup); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const submit = async e => { e.preventDefault(); setError(''); setSaving(true); try { await onSave({ name, url, group }); } catch (err) { setError(err.message); } finally { setSaving(false); } };
  return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><form className="modal" onSubmit={submit}><div className="modal-top"><span className="modal-icon"><Server size={19}/></span><button type="button" className="modal-close" onClick={onClose}><X size={17}/></button></div><h2>{editing ? 'Edit application' : 'Add an application'}</h2><p>{editing ? 'Update this endpoint and its monitoring group.' : 'Add an endpoint to your live application map.'}</p><label>Application name<input autoFocus value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Core API" required maxLength={80}/></label><label>URL or IP address<input value={url} onChange={e => setUrl(e.target.value)} placeholder="https://api.example.com or 192.168.1.20" required/><small>HTTP or HTTPS endpoint</small></label><label>Group<select value={groups.some(item => item.name === group) ? group : groups[0]?.name || 'Unassigned'} onChange={e => setGroup(e.target.value)}>{groups.map(item => <option value={item.name} key={item.id}>{item.name}</option>)}</select></label>{error && <div className="form-error"><AlertTriangle size={14}/>{error}</div>}<div className="modal-actions"><button type="button" className="button-secondary" onClick={onClose}>Cancel</button><button className="button-primary" disabled={saving}>{saving && <LoaderCircle size={15} className="spin"/>}{editing ? 'Save changes' : <><Plus size={16}/>Add application</>}</button></div></form></div>; }

export default App;
